```swift
let homophones: [(String, String)] = [("their", "they/them/their"), ("know", "no, know"), ("weigh", "way, weigh"), ("to", "too, to"), ("no", "know"), ("is", "is"), ("it seams", "it seems"), ("bee", "be"), ("eye", "I"), ("knot", "not"), ("aloud", "allowed"), ("right", "write"), ("butt", "but"), ("sum", "some")]
func correctHomophones(_ text: String) -> String {
    var words: [String] = text.components(separatedBy: CharacterSet.whitespacesAndNewlines.inverted)

    for (homophone, correction) in homophones {
        for i in 0..<words.count {
            if words[i] == homophone {
                words[i] = correction
                break
            }
        }
    }

    let correctedText = words.joined(separator: " ")
    return correctedText
}
